import { FLOOR_Y, SURFACE_Y, wrap } from "../world/bounds.js";
import { step } from "../world/movement.js";

const BELL = "violet";
const INNER = "plum";
const TENTACLES = "mediumpurple";

export function spawn(world) {
  return {
    y: SURFACE_Y + 80 + Math.random() * (FLOOR_Y - SURFACE_Y - 160),
    vx: 0.3 + Math.random() * 0.4,
    drift: Math.random() * Math.PI * 2,
  };
}

export function update(jellyfish, world) {
  jellyfish.vy = Math.sin(world.tick / 60 + jellyfish.drift) * 0.8;
  step(jellyfish);

  wrap(jellyfish);
}

export function draw(jellyfish, pen) {
  const pulse = 1 + Math.sin((jellyfish.age / 20) + jellyfish.drift) * 0.08;

  pen.stroke(TENTACLES, 2);
  for (let i = -1; i <= 1; i += 1) {
    const sway = Math.sin(jellyfish.age / 15 + i) * 4;
    pen.line(i * 8, 10, i * 8 + sway, 36);
  }

  pen.fill(BELL);
  pen.ellipse(0, 0, 22 * pulse, 18 * pulse);
  pen.fill(INNER);
  pen.ellipse(0, -2, 12 * pulse, 8 * pulse);
}

