import { ENERGY_MAX } from "../world/energy.js";
import { step } from "../world/movement.js";
import { keepInside, SURFACE_Y, FLOOR_Y } from "../world/bounds.js";

const BODY = "coral";
const BELLY = "peachpuff";
const CROWN = "gold";

// A small group of seahorses that bob gently up and down.
export const count = 3;

export function spawn() {
  return {
    vx: 0.2,
    energy: ENERGY_MAX,
    bobOffset: Math.random() * Math.PI * 2,
    bobSpeed: 0.05 + Math.random() * 0.04,
    bobSize: 6 + Math.random() * 6,
  };
}

export function update(seahorse, world) {
  seahorse.bobOffset += seahorse.bobSpeed;

  // Slow horizontal drift.
  seahorse.vx += (Math.random() - 0.5) * 0.02;
  seahorse.vx = Math.max(-0.6, Math.min(0.6, seahorse.vx));

  // Bob up and down around the middle of the water column.
  const waterMid = SURFACE_Y + (FLOOR_Y - SURFACE_Y) / 2;
  seahorse.y = waterMid + Math.sin(seahorse.bobOffset) * seahorse.bobSize;

  step(seahorse);
  keepInside(seahorse);
}

export function draw(seahorse, pen) {
  if (seahorse.vx < 0) pen.flip();

  // Body: upright seahorse profile.
  pen.fill(BODY);
  pen.ellipse(0, 0, 9, 16);

  // Belly pouch.
  pen.fill(BELLY);
  pen.ellipse(4, 4, 5, 8);

  // Snout.
  pen.fill(BODY);
  pen.ellipse(8, -10, 6, 3);

  // Crown.
  pen.fill(CROWN);
  pen.poly([-2, -14, 2, -22, 6, -14]);

  // Eye.
  pen.fill("black");
  pen.circle(7, -10, 1.5);

  // Curled tail.
  pen.stroke(BODY);
  pen.line(0, 18, -4, 24);
}

