const ARMS = 5;
const R1 = 24;
const R2 = 10;
const TURN_SPEED = 0.003;

const SKIN = "orange";
const BOTTOM = "sand";

export function spawn(world) {
  return {
    x: Math.random() * world.width,
    y: world.floorY - 6,
    angle: Math.random() * 2 * Math.PI,
  };
}

export function update(starfish) {
  starfish.angle += TURN_SPEED;
}

export function draw(starfish, pen) {
  pen.turn(starfish.angle);
  pen.fill(SKIN);
  const pts = [];
  for (let i = 0; i < ARMS * 2; i++) {
    const a = (i * Math.PI) / ARMS;
    const r = i % 2 === 0 ? R1 : R2;
    pts.push(Math.cos(a) * r, Math.sin(a) * r);
  }
  pen.poly(pts);
  pen.fill(BOTTOM);
  pen.circle(0, 0, R2 * 0.7);
}

