import { FLOOR_Y } from "../world/bounds.js";

const SPINES = "darkviolet";
const BODY = "black";

export function spawn() {
  return { y: FLOOR_Y - 9 };
}

export function update(urchin, world) {
  urchin.wave = Math.sin(world.tick / 12 + urchin.id * 2);
}

export function draw(urchin, pen) {
  pen.fill(BODY);
  pen.circle(0, 0, 10);
  pen.stroke(SPINES, 2);
  for (let i = 0; i < 12; i += 1) {
    const angle = (i / 12) * Math.PI * 2;
    const reach = 16 + urchin.wave * 3 * ((i % 2 === 0) ? 1 : -1);
    pen.line(
      Math.cos(angle) * 9,
      Math.sin(angle) * 9,
      Math.cos(angle) * reach,
      Math.sin(angle) * reach
    );
  }
}

