import { step, glide } from "../world/movement.js";
import { wrap } from "../world/bounds.js";

const BACK = "#3a4a60";
const BELLY = "#d8dce6";
const GILL = "#2a3545";

export const count = 2;

export function spawn(world) {
  return {
    x: Math.random() * world.width,
    y: world.surfaceY + 60 + Math.random() * (world.floorY - world.surfaceY - 120),
    vx: 0.4 + Math.random() * 0.4,
    vy: (Math.random() - 0.5) * 0.3,
    angle: 0,
    sweep: 0.015 + Math.random() * 0.01,
    radius: 120 + Math.random() * 80,
  };
}

export function update(manta, world) {
  manta.angle += manta.sweep;
  const turn = Math.cos(manta.angle) * 0.08;
  const ax = -manta.vy * turn;
  const ay = manta.vx * turn;
  manta.vx += ax;
  manta.vy += ay;
  const speed = Math.hypot(manta.vx, manta.vy);
  if (speed > 0) {
    manta.vx = (manta.vx / speed) * 0.9;
    manta.vy = (manta.vy / speed) * 0.9;
  }
  glide(manta, 0.999);
  step(manta);
  wrap(manta);
}

export function draw(manta, pen) {
  const heading = Math.atan2(manta.vy, manta.vx);
  pen.turn(heading);

  pen.fill(BACK);
  pen.poly([0, -10, 18, -28, 32, -8, 26, 12, 10, 18, -8, 14, -18, 2, -10, -6]);

  pen.fill(BELLY);
  pen.ellipse(2, 2, 16, 8);

  pen.fill(GILL);
  pen.poly([8, -2, 22, -6, 20, 4, 6, 6]);

  pen.stroke("black");
  pen.line(-14, 0, 32, 0);
}

