  wander(anglerfish, 0.04);
  glide(anglerfish, 0.96);
  step(anglerfish);
  bounce(anglerfish);

  const target = isNight(world) ? 1 : 0;
  anglerfish.light += (target - anglerfish.light) * 0.04;
