  pen.alpha(0.4 + 0.6 * glow);
  pen.circle(24, -22, 5);
  pen.alpha(1);

  // Body
  pen.fill(BODY);
  pen.ellipse(0, 0, 24, 14);
  pen.fill(BELLY);
  pen.ellipse(-2, 3, 16, 7);

  // Tail
  pen.fill(BODY);
  pen.poly([-20, 0, -34, -10, -34, 10]);

