import { step, glide, steer, distance } from "../world/movement.js";
import { wrap } from "../world/bounds.js";

const BODY = "steelblue";
const FIN = "cornflowerblue";
const SCHOOL_SIZE = 8;
const NEIGHBOUR_RADIUS = 60;
const TOO_CLOSE = 14;

export function spawn() {
  return { vx: 1, vy: 0 };
}

export const count = SCHOOL_SIZE;

export function update(fish, world) {
  steer(fish, fish.x + fish.vx * 30, fish.y + fish.vy * 30, 0.03);

  let cx = 0;
  let cy = 0;
  let count = 0;
  let close = 0;

  for (const other of world.creatures) {
    if (other === fish || other.kind !== fish.kind) continue;
    const d = distance(fish, other);
    if (d < NEIGHBOUR_RADIUS) {
      cx += other.x;
      cy += other.y;
      count++;
    }
    if (d > 0.001 && d < TOO_CLOSE) {
      fish.vx -= (other.x - fish.x) / d * 0.08;
      fish.vy -= (other.y - fish.y) / d * 0.08;
      close++;
    }
  }

  if (count > 0) {
    steer(fish, cx / count, cy / count, 0.06);
  }

  if (close === 0 && Math.random() < 0.02) {
    fish.vy += (Math.random() - 0.5) * 0.3;
  }

  glide(fish, 0.96);
  step(fish);
  wrap(fish);
}

export function draw(fish, pen) {
  if (fish.vx < 0) pen.flip();
  pen.fill(FIN);
  pen.poly([-6, 0, -11, -4, -11, 4]);
  pen.fill(BODY);
  pen.ellipse(0, 0, 9, 5);
  pen.fill("white");
  pen.circle(3, -1, 1.2);
  pen.fill("black");
  pen.circle(3.5, -1, 0.5);
}

