import { ENERGY_MAX, isHungry } from "../world/energy.js";
import { nearestFood } from "../world/food.js";
import { keepInside } from "../world/bounds.js";
import { step, steer, glide } from "../world/movement.js";

const SKIN = "darkviolet";
const BELLY = "plum";
const EYE = "white";
const PUPIL = "black";

export function spawn() {
  return { vx: 2, energy: ENERGY_MAX };
}

export function update(eel, world) {
  const food = isHungry(eel) ? nearestFood(eel, world) : null;
  if (food) steer(eel, food.x, food.y, 0.35);
  else steer(eel, eel.x + (eel.vx < 0 ? -120 : 120), eel.y, 0.08);
  glide(eel, 0.95);
  step(eel);
  keepInside(eel);
}

export function draw(eel, pen) {
  if (eel.vx < 0) pen.flip();

  // Long sinuous body made of overlapping circles.
  pen.fill(SKIN);
  for (let i = 0; i < 7; i += 1) {
    const t = i / 6;
    const bx = -32 + t * 52;
    const by = Math.sin((eel.age + i * 8) * 0.3) * (2 + i * 0.4);
    pen.circle(bx, by, 6 - i * 0.4);
  }

  pen.fill(BELLY);
  pen.ellipse(18, 3, 10, 5);

  pen.fill(EYE);
  pen.circle(22, -4, 3);
  pen.fill(PUPIL);
  pen.circle(23, -4, 1.5);
}

