import { ENERGY_MAX } from "../world/energy.js";
import { step, wander, glide } from "../world/movement.js";
import { keepInside } from "../world/bounds.js";

const BODY = "#f5c878";
const BELLY = "#fff8e1";
const SPOTS = "#5a4a3a";
const EYE = "black";
const PUFF_UP_DISTANCE = 90;
const PUFF_DEFLATE_TIME = 120;

export function spawn() {
  return { vx: 0.5, energy: ENERGY_MAX, size: 0, puffTimer: 0 };
}

function nearestOther(pufferfish, world) {
  let best = null;
  let bestFar = Infinity;
  for (const creature of world.creatures) {
    if (creature.id === pufferfish.id) continue;
    const far = Math.hypot(creature.x - pufferfish.x, creature.y - pufferfish.y);
    if (far < bestFar) {
      best = creature;
      bestFar = far;
    }
  }
  return { creature: best, far: bestFar };
}

export function update(pufferfish, world) {
  const near = nearestOther(pufferfish, world);
  const threatened = near.creature && near.far <= PUFF_UP_DISTANCE;

  if (threatened) {
    pufferfish.puffTimer = PUFF_DEFLATE_TIME;
  } else if (pufferfish.puffTimer > 0) {
    pufferfish.puffTimer -= 1;
  }

  const target = threatened ? 1 : 0;
  pufferfish.size += (target - pufferfish.size) * 0.08;

  if (threatened) {
    pufferfish.vx *= 0.92;
    pufferfish.vy *= 0.92;
  } else if (pufferfish.size < 0.1) {
    wander(pufferfish, 0.05);
    glide(pufferfish, 0.98);
  } else {
    glide(pufferfish, 0.96);
  }

  step(pufferfish);
  keepInside(pufferfish);
}

export function draw(pufferfish, pen) {
  const s = 1 + pufferfish.size * 1.4;
  if (pufferfish.vx < 0) pen.flip();

  pen.fill(BODY);
  pen.circle(0, 0, 14 * s);

  pen.fill(BELLY);
  pen.ellipse(3 * s, 4 * s, 9 * s, 6 * s);

  pen.fill(SPOTS);
  pen.circle(-6 * s, -5 * s, 2 * s);
  pen.circle(5 * s, -7 * s, 2.5 * s);

  pen.fill(EYE);
  pen.circle(8 * s, -4 * s, 3 * s);

  pen.fill(BODY);
  pen.poly([-12 * s, 0, -22 * s, -7 * s, -22 * s, 7 * s]);
}

