import { ENERGY_MAX, isHungry } from "../world/energy.js";
import { nearestFood } from "../world/food.js";
import { keepInside } from "../world/bounds.js";
import { step, steer, glide, distance } from "../world/movement.js";

const BODY = "blue";
const STRIPE = "white";

function findTurtle(cleaner, world) {
  let nearest = null;
  let best = Infinity;
  for (const creature of world.creatures) {
    if (creature.kind !== "turtle") continue;
    const far = distance(cleaner, creature);
    if (far < best) {
      best = far;
      nearest = creature;
    }
  }
  return nearest;
}

export function spawn() {
  return { vx: 1, energy: ENERGY_MAX };
}

export function update(cleaner, world) {
  const turtle = findTurtle(cleaner, world);
  if (turtle) {
    const offsetX = turtle.vx < 0 ? -22 : 22;
    const offsetY = 10;
    steer(cleaner, turtle.x + offsetX, turtle.y + offsetY, 0.12);
  } else {
    steer(cleaner, cleaner.x + (cleaner.vx < 0 ? -60 : 60), cleaner.y, 0.04);
  }

  const food = isHungry(cleaner) ? nearestFood(cleaner, world) : null;
  if (food) steer(cleaner, food.x, food.y, 0.18);

  glide(cleaner, 0.96);
  step(cleaner);
  keepInside(cleaner);
}

export function draw(cleaner, pen) {
  if (cleaner.vx < 0) pen.flip();
  pen.fill(STRIPE);
  pen.poly([-10, 0, -22, -9, -22, 9]);
  pen.fill(BODY);
  pen.ellipse(0, 0, 16, 9);
  pen.fill(STRIPE);
  pen.ellipse(-2, 0, 2.5, 8);
  pen.ellipse(6, 0, 2.5, 7);
}

