import { ENERGY_MAX } from "../world/energy.js";
import { FLOOR_Y, bounce } from "../world/bounds.js";
import { step, wander, glide } from "../world/movement.js";

const SHELL = "crimson";
const LEGS = "darkorange";
const EYE = "black";

const HIDE_BELOW = ENERGY_MAX * 0.30;

export function spawn() {
  return { y: FLOOR_Y - 6, vx: 0.8, energy: ENERGY_MAX };
}

export function update(crab, world) {
  if (crab.energy < HIDE_BELOW) {
    crab.hiding = true;
    glide(crab, 0.8);
  } else {
    crab.hiding = false;
    wander(crab, 0.15);
  }
  step(crab);
  bounce(crab);
}

export function draw(crab, pen) {
  if (crab.vx < 0) pen.flip();

  pen.fill(SHELL);
  pen.ellipse(0, 0, 18, 12);

  if (!crab.hiding) {
    pen.fill(LEGS);
    pen.line(-10, 4, -18, 14);
    pen.line(-4, 6, -8, 16);
    pen.line(4, 6, 8, 16);
    pen.line(10, 4, 18, 14);
    pen.fill(EYE);
    pen.circle(8, -6, 2);
    pen.circle(14, -6, 2);
    pen.line(6, -10, 10, -10);
    pen.line(12, -10, 16, -10);
  }
}

