import { ENERGY_MAX } from "../world/energy.js";
import { step, glide, wander } from "../world/movement.js";
import { keepInside } from "../world/bounds.js";
import { nearestFood, eatNearby } from "../world/food.js";

const SHELL_COLOUR = "#8fbc8f";
const DARK_SHELL = "#556b2f";
const LEG_COLOUR = "#d2691e";
const EYE_COLOUR = "#2f2f2f";

const SIZE = 22;
const MAX_SPEED = 1.2;
const WANDER_PUSH = 0.3;
const GLIDE = 0.92;
const HIDE_BELOW = ENERGY_MAX / 3;

export function spawn(world) {
  return {
    x: world.poolWidth / 2 + (Math.random() - 0.5) * 200,
    y: world.poolHeight * 0.8 + (Math.random() - 0.5) * 40,
    vx: 0,
    vy: 0,
    energy: ENERGY_MAX,
    hiding: false
  };
}

export function update(crab, world) {
  if (crab.energy < HIDE_BELOW) {
    crab.hiding = true;
  } else if (crab.energy > HIDE_BELOW + 10) {
    crab.hiding = false;
  }

  if (crab.hiding) {
    crab.vx = 0;
    crab.vy = 0;
    return;
  }

  const food = nearestFood(crab, world);
  if (food) {
    const dx = food.x - crab.x;
    const dy = food.y - crab.y;
    const far = Math.hypot(dx, dy);
    if (far > 0.001) {
      crab.vx += (dx / far) * 0.4;
      crab.vy += (dy / far) * 0.4;
    }
  } else {
    wander(crab, WANDER_PUSH);
  }

  eatNearby(crab, world);

  const speed = Math.hypot(crab.vx, crab.vy);
  if (speed > MAX_SPEED) {
    crab.vx = (crab.vx / speed) * MAX_SPEED;
    crab.vy = (crab.vy / speed) * MAX_SPEED;
  }

  step(crab);
  glide(crab, GLIDE);
  keepInside(crab);

  crab.y = Math.max(crab.y, world.floorY - 10);
}

export function draw(crab, pen, world) {
  if (crab.hiding) {
    pen.fill(SHELL_COLOUR);
    pen.ellipse(0, SIZE / 4, SIZE, SIZE * 0.6);
    pen.fill(DARK_SHELL);
    pen.ellipse(-SIZE * 0.25, SIZE / 8, SIZE * 0.4, SIZE * 0.35);
    pen.ellipse(SIZE * 0.25, SIZE / 8, SIZE * 0.4, SIZE * 0.35);
    return;
  }

  for (const side of [-1, 1]) {
    const legX = side * SIZE * 0.55;
    pen.stroke(LEG_COLOUR);
    pen.line(legX, 0, legX + side * SIZE * 0.35, -SIZE * 0.4);
    pen.line(legX, 0, legX + side * SIZE * 0.45, SIZE * 0.1);
    pen.line(legX, 0, legX + side * SIZE * 0.35, SIZE * 0.5);
  }

  pen.fill(SHELL_COLOUR);
  pen.ellipse(0, 0, SIZE, SIZE * 0.55);

  pen.fill(DARK_SHELL);
  pen.circle(-SIZE * 0.35, -SIZE * 0.1, SIZE * 0.13);
  pen.circle(SIZE * 0.35, -SIZE * 0.1, SIZE * 0.13);

  pen.fill(EYE_COLOUR);
  pen.circle(-SIZE * 0.28, -SIZE * 0.22, SIZE * 0.08);
  pen.circle(SIZE * 0.28, -SIZE * 0.22, SIZE * 0.08);

  pen.fill(LEG_COLOUR);
  for (const side of [-1, 1]) {
    const clawX = side * SIZE * 0.75;
    pen.circle(clawX, -SIZE * 0.15, SIZE * 0.12);
  }
}

export const count = 3;

